#ifdef GL_ES
precision mediump float;
#endif



//=====================================================
// 1) Quaternion Tools for Spin(4) rotation
//=====================================================
vec4 quatMul(in vec4 q1, in vec4 q2)
{
    // q1=(w1,x1,y1,z1), q2=(w2,x2,y2,z2)
    float w = q1.x*q2.x - (q1.y*q2.y + q1.z*q2.z + q1.w*q2.w);
    float x = q1.x*q2.y + q2.x*q1.y + (q1.z*q2.w - q1.w*q2.z);
    float y = q1.x*q2.z + q2.x*q1.z + (q1.w*q2.y - q1.y*q2.w);
    float z = q1.x*q2.w + q2.x*q1.w + (q1.y*q2.z - q1.z*q2.y);
    return vec4(w,x,y,z);
}

vec4 quatConj(in vec4 q) {
    // Conjugate:  (w, -x, -y, -z)
    return vec4(q.x, -q.y, -q.z, -q.w);
}

vec4 vec4ToQuat(in vec4 p4)
{
    // interpret p4=(x,y,z,w) as quaternion q=(w, x, y, z).
    return vec4(p4.w, p4.x, p4.y, p4.z);
}
vec4 quatToVec4(in vec4 q)
{
    // interpret q=(qw,qx,qy,qz) back as p4=(qx,qy,qz,qw).
    return vec4(q.y, q.z, q.w, q.x);
}

// Apply p-> qL * p * conj(qR)
vec4 rotate4D_Lie(in vec4 p4, in vec4 qL, in vec4 qR)
{
    vec4 qp = vec4ToQuat(p4);
    vec4 qRc = quatConj(qR);
    vec4 t1  = quatMul(qL, qp);
    vec4 outQ= quatMul(t1, qRc);
    return quatToVec4(outQ);
}

//=====================================================
// 2) Building qL,qR for time-based Spin(4)
//=====================================================
vec4 buildQuaternion(float time, float phase)
{
    // slower angle
    float angle = 0.12*time + phase;
    float halfv  = 0.5*angle;
    vec3 axis   = normalize(vec3(sin(0.1*time), cos(0.2*time), sin(0.1*time+phase)));
    float w = cos(halfv);
    float s = sin(halfv);
    return vec4(w, s*axis.x, s*axis.y, s*axis.z);
}
void getSpin4(float t, out vec4 qL, out vec4 qR)
{
    qL = buildQuaternion(t, 0.0);
    qR = buildQuaternion(t, 1.57); // ~pi/2 offset
}

//=====================================================
// 3) Inverse Stereographic: R^3 -> S^3
//=====================================================
vec4 invStereo3D(vec3 P)
{
    float R2 = dot(P,P);
    float denom = R2 + 1.0;
    denom = max(denom, 1e-9);

    float x = 2.0*P.x/denom;
    float y = 2.0*P.y/denom;
    float z = 2.0*P.z/denom;
    float w = (R2 - 1.0)/denom;
    return vec4(x,y,z,w);
}

//=====================================================
// 4) 4D Menger membership (NO CLIPPING)
//=====================================================
bool inMenger4D(vec4 p4)
{
    vec4 z = p4;
    const int N=6; 
    for(int i=0;i<N;i++)
    {
        z *= 3.0;
        z  = mod(z + 1.0, 2.0) - 1.0;
        // hole check
        if(max(abs(z.x), max(abs(z.y), max(abs(z.z), abs(z.w)))) < 0.5)
        {
            return false;
        }
    }
    return true;
}

//=====================================================
// 5) Hopf Map: S^3 -> S^2, plus fiber angle
//    One standard formula for Hopf fibration is:
//    Hopf(x,y,z,w) -> ( 2(xw+yz), 2(yw - xz), w^2+z^2 - x^2 - y^2 ) in S^2.
//    The fiber angle can be gleaned from leftover phase
//    (there are many ways to define it).
//=====================================================
struct HopfResult {
    vec3 baseS2;   // a point on S^2
    float fiberAngle; 
};

HopfResult hopfMap(vec4 p4)
{
    // p4 is on S^3 => x^2+y^2+z^2+w^2=1
    float x = p4.x;
    float y = p4.y;
    float z = p4.z;
    float w = p4.w;

    // S^2 base
    vec3 base = vec3(
        2.0*(x*w + y*z),
        2.0*(y*w - x*z),
        w*w + z*z - x*x - y*y
    );
    // Should have length ~1, but we normalize for safety
    float lenb = max(length(base), 1e-9);
    base /= lenb;

    // A possible “fiber angle”
    // We'll pick an angle from the ratio (x+iy)/(z+iw), etc.
    // or a simpler approach: let's define
    //   phi = atan2( x, w ) or something. This is one possible measure.
    // We'll do phi = atan2( x, w ) + atan2( y, z ) for fun:
    float phi = atan(y,z) + atan(x,w);

    HopfResult hr;
    hr.baseS2 = base;
    hr.fiberAngle = phi;
    return hr;
}

//=====================================================
// 6) fractalVal3D => returns +1 or -1 and also Hopf data
//    so we can color or filter by the fiber section
//=====================================================
struct FracData {
    float val;       // +1 in fractal, -1 outside
    bool inSet;      // (val>0)
    vec3 baseS2;     // Hopf base
    float fiberAngle;// Hopf fiber angle
};

FracData fractalInfo3D(vec3 p3, float time, vec4 qL, vec4 qR)
{
    FracData fd;
    fd.val = -1.0;
    fd.inSet= false;
    fd.baseS2= vec3(0);
    fd.fiberAngle= 0.0;

    // 1) Lift
    vec4 p4 = invStereo3D(p3);

    // 2) spin(4)
    p4 = rotate4D_Lie(p4, qL, qR);

    // 3) membership
    bool inside = inMenger4D(p4);

    // 4) hopf
    HopfResult hr = hopfMap(p4);

    fd.val = inside? 1.0 : -1.0;
    fd.inSet= inside;
    fd.baseS2= hr.baseS2;
    fd.fiberAngle= hr.fiberAngle;

    return fd;
}

//=====================================================
// 7) Normal estimation
//=====================================================
vec3 estimateNormal(vec3 p3, float e, float t, vec4 qL, vec4 qR)
{
    FracData c0 = fractalInfo3D(p3, t, qL, qR);
    float c = c0.val;

    vec3 G=vec3(0.0);
    vec3[6] offs = vec3[](
       vec3(e,0,0), vec3(-e,0,0),
       vec3(0,e,0), vec3(0,-e,0),
       vec3(0,0,e), vec3(0,0,-e)
    );
    for(int i=0;i<6;i++)
    {
        FracData cf = fractalInfo3D(p3+offs[i], t, qL, qR);
        float dv = cf.val - c;
        G += offs[i]*dv;
    }
    return normalize(G);
}

//=====================================================
// 8) Sky
//=====================================================
vec3 skyColor(vec3 dir)
{
    float u=0.5*(dir.y+1.0);
    return mix(vec3(0.7,0.8,1.0), vec3(0.3,0.4,0.7), u);
}

//=====================================================
// 9) renderScene: membership-based raymarch
//    *With optional "fiber section" filtering* 
//=====================================================
vec4 renderScene(vec2 fragCoord)
{
    // camera
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.y;
    vec3 camPos=vec3(0,0,3);
    vec3 camTarget=vec3(0);
    vec3 camDir=normalize(camTarget-camPos);
    vec3 camRight=normalize(cross(vec3(0,1,0),camDir));
    vec3 camUp=cross(camDir, camRight);

    vec3 rd=normalize(camDir + uv.x*camRight + uv.y*camUp);

    // quaternions
    vec4 qL,qR;
    getSpin4(iTime,qL,qR);

    float stepSz=0.02;
    float tMax=10.0;
    int maxSteps=500;

    bool wasIn=false;
    bool hit=false;
    vec3 hitPos=vec3(0);

    // Optionally define a "fiber slice" angle and tolerance
    float targetFiber = 0.0;   // e.g. we want fiberAngle ~ 0
    float tol = 0.2;          // range around that angle
    bool fiberSlice = false;  // set to true if you want to restrict to that slice

    for(int i=0;i<maxSteps;i++)
    {
        float t=float(i)*stepSz;
        if(t>tMax) break;
        vec3 pos=camPos+rd*t;
        FracData fd = fractalInfo3D(pos, iTime, qL, qR);

        bool inside = fd.inSet;

        // If we want to do a fiber-slice section:
        if(fiberSlice && inside)
        {
            // unroll angle so difference is mod 2pi
            float dAngle = fd.fiberAngle - targetFiber;
            // shift to [-pi,pi] range
            dAngle = mod(dAngle+3.14159, 6.28318)-3.14159;
            inside = (abs(dAngle)<tol);
        }

        if(!wasIn && inside)
        {
            hit=true;
            hitPos=pos;
            break;
        }
        wasIn=inside;
    }

    if(!hit)
    {
        return vec4(skyColor(rd),1.0);
    }

    // normal
    vec3 N=estimateNormal(hitPos,0.001,iTime,qL,qR);
    vec3 R=reflect(-rd,N);

    // reflection
    vec3 col=skyColor(R);

    // For fun, let's color by fiber angle if you'd like:
    // get fractal info at the hit
    FracData infoAtHit = fractalInfo3D(hitPos,iTime,qL,qR);
    float angle = mod(infoAtHit.fiberAngle, 6.28318);
    angle/=6.28318; // [0..1]

    // blend reflection with a hue from fiberAngle
    vec3 fiberHue = vec3(0.5+0.5*sin(6.28318*angle),
                         0.5+0.5*sin(6.28318*angle+2.094),
                         0.5+0.5*sin(6.28318*angle+4.188));
    col = mix(col, fiberHue, 0.4); // 40% tinted by fiber color

    return vec4(col,1.0);
}

//=====================================================
// 10) mainImage: 2×2 multi-sampling
//=====================================================
void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 px = fragCoord;
    vec2 offs[4] = vec2[](
      vec2(-0.25,-0.25),
      vec2( 0.25,-0.25),
      vec2(-0.25, 0.25),
      vec2( 0.25, 0.25)
    );
    vec4 col=vec4(0.0);
    for(int i=0;i<4;i++)
    {
        col += renderScene(px+offs[i]);
    }
    col*=0.25;
    fragColor=col;
}
